parameters.template:
{% set power_l = states('sensor.waschkeller_waschmaschine_links_power') | float(0) %}
{% set power_r = states('sensor.waschkeller_waschmaschine_rechts_power') | float(0) %}
{% set power = [power_l, power_r] | max %}
{% set old = states('sensor.waschkeller_waschmaschine_status_text') if states('sensor.waschkeller_waschmaschine_status_text') not in ['unknown', 'unavailable', ''] else 'Aus' %}

Power: {{ power }}W, Old: {{ old }}

{% if power > 50 %}
  Laeuft
{% elif power > 0 %}
  Standby
{% elif old == 'Laeuft' %}
  Fertig
{% elif old == 'Fertig' %}
  Fertig
{% else %}
  Aus
{% endif %}

